head.script:
scwin.onpageload = function() {

};


scwin.getCustomType = function(info){
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo ;

    var _col1 = dlt_list.getCellData( rowIndex ,'col1' );
    if( _col1 == 'a' ){
        returnInfo = {
            id : "dynamic_text_readOnly_" + rowIndex + "_" + colIndex,
            inputType : "text",
            options : {
                readOnly: true
            }
        }

    }else {
        returnInfo = {
            id : "dynamic_text_disabled_" + rowIndex + "_" + colIndex,
            inputType : "text",
            options : {
                disabled: true
            }
        }
    }

    return returnInfo;

};

scwin.grd1_onafteredit = function(row,col,value) {
    var colId = this.getColumnID( col );
    if (colId == "col1"){
        this.refreshCell( row , "col2" );
        dlt_list.setCellData( row , "col2" , "" );
    }
};

scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkVal1 = function() {
	return WebSquare.wUnit.getJq('#grd1_cell_0_1').hasClass('w2grid_default_readonly');
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('G_'+$p.id+'grd1__dynamic_text_readOnly_0_1') == null;
}
scwin.unitTest = function() {

    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
